<section class="page-head"><span class="eyebrow">INTELLIGENCE FEED</span><h1>Latest updates</h1><p>News imported from configured sources and clearly labelled editorial additions.</p></section><div class="feed large"><?php foreach($updates as $u):?><article class="feed-row"><div><small><?=e($u['game_name'])?> · <?=date('j M Y H:i',strtotime($u['published_at']))?></small><h2><?=e($u['title'])?></h2><p><?=e(mb_strimwidth(strip_tags($u['body']??''),0,360,'…'))?></p><a class="source" href="<?=e($u['source_url'])?>" target="_blank" rel="noopener">Source: <?=e($u['source_name'])?> ↗</a></div><span class="verified"><?=((int)$u['verified']?'VERIFIED':'EDITORIAL')?></span></article><?php endforeach;?></div>